/** Декодированный package-lock.json по ключу `<tool>@<version>`, или null. */
export function getNpmLock(tool: string, version: string): string | null {
  const b64 = NPM_LOCKS_B64[`${tool}@${version}`];
  if (!b64) return null;
  return Buffer.from(b64, 'base64').toString('utf8');
}
